import { test, expect } from '@playwright/test';

test.describe('CRUD Operations - Duplicate Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should duplicate an existing record successfully', async ({ page }) => {
    // Locate and click the duplicate button for the first record
    await page.getByRole('button', { name: 'Duplicate' }).first().click();

    // Verify that a success message is displayed
    const successMessage = await page.getByText('Record duplicated successfully');
    await expect(successMessage).toBeVisible();

    // Verify that the new record appears in the list
    const newRecord = await page.getByText('New Record Name'); // Adjust the text as necessary
    await expect(newRecord).toBeVisible();
  });

  test('should not duplicate if no record is selected', async ({ page }) => {
    // Attempt to click the duplicate button without selecting a record
    await page.getByRole('button', { name: 'Duplicate' }).click();

    // Verify that an error message is displayed
    const errorMessage = await page.getByText('No record selected for duplication');
    await expect(errorMessage).toBeVisible();
  });
});
